## 六、校验规则

```javascript
// src/validators/auth.js
const { body } = require('express-validator')

const registerRules = [
  body('username')
    .trim()
    .notEmpty().withMessage('用户名不能为空')
    .isLength({ min: 2, max: 20 }).withMessage('用户名长度 2-20 个字符')
    .matches(/^[\w\u4e00-\u9fa5]+$/).withMessage('用户名只能包含字母、数字、下划线和中文'),

  body('email')
    .trim()
    .notEmpty().withMessage('邮箱不能为空')
    .isEmail().withMessage('邮箱格式不正确')
    .normalizeEmail(),

  body('password')
    .notEmpty().withMessage('密码不能为空')
    .isLength({ min: 6, max: 50 }).withMessage('密码长度 6-50 个字符')
]

const loginRules = [
  body('email').trim().notEmpty().withMessage('邮箱不能为空').isEmail().withMessage('邮箱格式不正确'),
  body('password').notEmpty().withMessage('密码不能为空')
]

module.exports = { registerRules, loginRules }
```

