## 三、路由处理

### 3.1 基础路由

```javascript
const http = require('http')
const url = require('url')

const server = http.createServer((req, res) => {
  // req.url 不完整 → 必须补协议域名 → 才能用 JS 内置的 URL 解析路径
  const { pathname } = new URL(req.url, `http://${req.headers.host}`)
  const method = req.method

  res.setHeader('Content-Type', 'application/json; charset=utf-8')

  // 路由匹配
  if (method === 'GET' && pathname === '/') {
    res.end(JSON.stringify({ message: '欢迎访问首页' }))

  } else if (method === 'GET' && pathname === '/api/users') {
    const users = [
      { id: 1, name: '张三' },
      { id: 2, name: '李四' }
    ]
    res.end(JSON.stringify(users))

  } else if (method === 'GET' && pathname.startsWith('/api/users/')) {
    const id = pathname.split('/').pop()
    res.end(JSON.stringify({ id, name: '用户' + id }))

  } else {
    res.statusCode = 404
    res.end(JSON.stringify({ error: '页面不存在' }))
  }
})

server.listen(3000)
```

### 3.2 返回 HTML 页面

```javascript
const http = require('http')
const fs = require('fs')
const path = require('path')

const server = http.createServer((req, res) => {
  const { pathname } = new URL(req.url, `http://${req.headers.host}`)

  // 根据路径返回不同文件
  let filePath = path.join(__dirname, 'public', pathname === '/' ? 'index.html' : pathname)

  // 根据扩展名设置 Content-Type
  const extMap = {
    '.html': 'text/html; charset=utf-8',
    '.css': 'text/css',
    '.js': 'application/javascript',
    '.png': 'image/png',
    '.jpg': 'image/jpeg',
    '.json': 'application/json'
  }
  const ext = path.extname(filePath)
  const contentType = extMap[ext] || 'text/plain'

  // 读取文件并响应
  fs.readFile(filePath, (err, data) => {
    if (err) {
      res.statusCode = 404
      res.end('<h1>404 Not Found</h1>')
      return
    }
    res.setHeader('Content-Type', contentType)
    res.end(data)
  })
})

server.listen(3000)
```

