## 五、处理 POST 请求体

POST 请求的数据在请求体（Body）中，需要通过监听 `data` 和 `end` 事件来收集：

```javascript
const http = require('http')

const server = http.createServer((req, res) => {
  if (req.method !== 'POST') {
    res.statusCode = 405
    res.end('Method Not Allowed')
    return
  }

  // 收集请求体数据（可能分多次传输）
  let body = ''

  req.on('data', (chunk) => {
    body += chunk.toString()
    // 防止恶意大请求（限制 1MB）
    if (body.length > 1e6) {
      req.destroy()
    }
  })

  req.on('end', () => {
    try {
      // 解析 JSON 格式的请求体
      const data = JSON.parse(body)
      console.log('收到数据:', data)

      res.setHeader('Content-Type', 'application/json')
      res.end(JSON.stringify({ success: true, received: data }))
    } catch (err) {
      res.statusCode = 400
      res.end(JSON.stringify({ error: '请求体格式错误' }))
    }
  })

  req.on('error', (err) => {
    console.error('请求错误:', err)
    res.statusCode = 500
    res.end('Server Error')
  })
})

server.listen(3000)
```

### 5.1 处理表单数据（application/x-www-form-urlencoded）

```javascript
req.on('end', () => {
  // 表单数据格式：name=Alice&age=25
  const params = new URLSearchParams(body)
  const name = params.get('name')
  const age = params.get('age')

  console.log({ name, age })
  res.end(JSON.stringify({ name, age }))
})
```

