import { reactive, readonly, shallowReadonly } from 'vue';
let obj = reactive(
  {
    myname: {
      firstName: 'zhang',
      lastName: 'san'
    },
    myage: 18
  }
)
//1、 readonly()
let readonlyobj = readonly(obj)
// 2、shallowReadonly
let shallowReadonlyObj = shallowReadonly(obj)

</script>
