### 5.3.2、配置vue-router
src/router/index.ts	配置路由器对象，并暴露

```javascript
import {createRouter,createWebHistory} from 'vue-router'
// 导入路由组件
import Index from '../views/index.vue'
import News from '../views/news.vue'
import Car from '../views/car.vue'
import Mine from '../views/mine.vue'
// 配置路由路径
const routes=[
    {
        path:"/index",
        component:Index
    },
    {
        path:"/news",
        component:News
    },
    {
        path:"/car",
        component:Car
    },
    {
        path:"/mine",
        component:Mine
    }
]
// 创建路由
const router =createRouter({
    // 不仅要有路由规则，还要设置监听URL的模式
    // 用于配置路由模式的选项。
    // 它指定了路由应该使用 HTML5 的历史记录 API (window.history) 来实现导航
    history:createWebHistory(),
    routes
})
// 对外暴露
export default router
```

