  <div>
    <h3>{{ msg }}</h3>
    <input type="text" v-model="keyword">
    <button @click="addList">add</button>
    <ul>
      <li v-for="item in contentList" :key="item.id">
        {{ item.value }}
        <button @click="delFun(item.id)">del</button>
      </li>
    </ul>
  </div>
