### 1.3.4、axios的拦截器
axios给我们提供了两大类拦截器

请求方向的拦截（成功请求，失败请求）

响应方向的拦截（成功的，失败的）

拦截器的作用，用于我们在网络请求的时候，在发起请求或者响应时对操作进行处理

例如：发送请求时，可以添加网页加载的动画，或认证token，强制用户先登录再请求数据

响应的时候，可以结束网页加载的动画，或者对响应的数据进行处理



#### 1.3.4.1、请求拦截器
```html
<!DOCTYPE html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <title>Document</title>
    <script src="../js/axios.js"></script>
  </head>
  <body>
    <button id="btn" onclick="getData()">发送请求</button>
    <script>
      // 请求拦截器
      async function getData() {
        axios.interceptors.request.use(
          (config) => {
            // 发生请求前的一系列的处理
            console.log("开启加载动画");
            console.log("认证是否有token，如果没有，要去登录");
            return config; //拦截后的放行
          },
          (err) => {
            // 请求错误处理
            return Promise.reject(err);
          }
        );
        let res = await axios.get("http://localhost:3000/list");
        console.log(res.data);
      }
    </script>
  </body>
</html>
```

#### 1.3.4.2、相应拦截器
```html
<!DOCTYPE html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <title>Document</title>
    <script src="../js/axios.js"></script>
  </head>
  <body>
    <button id="btn" onclick="getData()">发送请求</button>
    <script>
      // 响应拦截器
      async function getData() {
        axios.interceptors.response.use(
          (config) => {
            // 数据回来前的一系列的处理
            console.log("关闭加载动画");
            console.log("对数据进行一些数据");
            return config.data; //拦截后的放行
          },
          (err) => {
            // 响应错误处理
            return Promise.reject(err);
          }
        );
        let res = await axios.get("http://localhost:3000/list");
        console.log(res.data);
      }
    </script>
  </body>
</html>
```

#### 1.3.4.3、取消拦截
```html
<!DOCTYPE html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <title>Document</title>
    <script src="../js/axios.js"></script>
  </head>
  <body>
    <button id="btn" onclick="getData()">发送请求</button>
    <script>
      // 请求拦截器
      async function getData() {
        let instance = axios.create();
        instance.interceptors.request.use(
          (config) => {
            // 发生请求前的一系列的处理
            console.log("开启加载动画");
            console.log("认证是否有token，如果没有，要去登录");
            return config; //拦截后的放行
          },
          (err) => {
            // 请求错误处理
            return Promise.reject(err);
          }
        );

        // 取消拦截
        axios.interceptors.request.eject(instance);

        let res = await axios.get("http://localhost:3000/list");
        console.log(res.data);
      }
    </script>
  </body>
</html>
```

