import { getmsgMixins } from '../mixins.js'
export default {
    // 2、组件中的方法名跟混入的方法名重复了
    // methods: {
    //     getmsg(){
    //       console.log('我是另外一个getmsg函数');
    //     }
    // },
    // 3、生命周期函数重复了
    mounted(){
        console.log('我是son组件中的mounted函数');
    }
}
</script>

```

