        <h1>{{msg}}</h1>
        <!-- 3. 使用组件 -->
        <userlogin></userlogin>
    </div>
    <script>
        // 1. 创建组件
        const userLoginComponent = {
            template: `
                <div>
                    <h3>用户登录</h3>
