});

console.log(newArr);
```

### 2.9.2、列表过滤`watch`属性实现
```html
<body>
  <div id="app">
    <h1>{{msg}}</h1>
    <input type="text" placeholder="请输入搜索关键字" v-model="keyword" />
    <table>
      <tr>
        <th>序号</th>
        <th>姓名</th>
        <th>薪资</th>
        <th>选择</th>
      </tr>
      <tr v-for="(hero,index) in filteredHeros" :key="hero.id">
        <td>{{index+1}}</td>
        <td>{{hero.name}}</td>
        <td>{{hero.power}}</td>
        <td><input type="checkbox" /></td>
      </tr>
    </table>
  </div>
  <script>
    const vm = new Vue({
      el: "#app",
      data: {
        keyword: "",
        msg: "列表过滤",
        heros: [
          { id: "101", name: "章三", power: 10000 },
          { id: "102", name: "三响", power: 9000 },
          { id: "103", name: "李四", power: 8000 },
          { id: "104", name: "李章", power: 6000 },
        ],
        filteredHeros: [],
      },
      watch: {
        keyword: {
          immediate: true,
          handler(val) {
            this.filteredHeros = this.heros.filter((hero) => {
              return hero.name.indexOf(val) >= 0;
            });
          },
        },
      },
    });
  </script>
</body>

```

