      width: 100px;
      height: 100px;
    }
    .active {
      background-color: green;
    }
    .text-danger {
      color: red;
    }
  </style>
</head>
<body>
  <div id="app">
    <h1>{{msg}}</h1>
    <!-- 静态写法 -->
    <div class="static active text-danger">{{msg}}</div>
    <br />
