### 2.5.6. computed和watch如何选择？
#### 比大小的案例
##### 2.5.6.1、watch实现
```html
<body>
  <div id="app">
    <h1>{{msg}}</h1>
    数值1：<input type="number" v-model="num1" /><br />
    数值2：<input type="number" v-model="num2" /><br />
    比较大小：{{compareResult}}
  </div>
  <script>
    const vm = new Vue({
      el: "#app",
      data: {
        msg: "比较大小的案例",
        num1: 0,
        num2: 0,
        compareResult: "",
      },
      watch: {
        // 监视num1
        num1: {
          immediate: true,
          handler(val) {
            let result = val - this.num2;
            if (result == 0) {
              this.compareResult = val + " = " + this.num2;
            } else if (result > 0) {
              this.compareResult = val + " > " + this.num2;
            } else {
              this.compareResult = val + " < " + this.num2;
            }
          },
        },
        // 监视num2
        num2: {
          immediate: true,
          handler(val) {
            let result = this.num1 - val;
            if (result == 0) {
              this.compareResult = this.num1 + " = " + val;
            } else if (result > 0) {
              this.compareResult = this.num1 + " > " + val;
            } else {
              this.compareResult = this.num1 + " < " + val;
            }
          },
        },
      },
    });
  </script>
</body>

```

##### 2.5.6.2、computed实现
```html
<body>
  <div id="app">
    <h1>{{msg}}</h1>
    数值1：<input type="number" v-model="num1" /><br />
    数值2：<input type="number" v-model="num2" /><br />
    比较大小：{{compareResult}}
  </div>
  <script>
    const vm = new Vue({
      el: "#app",
      data: {
        msg: "比较大小的案例",
        num1: 0,
        num2: 0,
      },
      computed: {
        // 计算属性的简写形式
        compareResult() {
          let result = this.num1 - this.num2;
          if (result == 0) {
            return this.num1 + " = " + this.num2;
          } else if (result > 0) {
            return this.num1 + " > " + this.num2;
          } else {
            return this.num1 + " < " + this.num2;
          }
        },
      },
    });
  </script>
</body>

```

##### 2.5.6.3、总结
1. 以上比较大小的案例可以用`computed`完成，并且比`watch`还要简单。所以要遵守一个原则：`computed`和`watch`都能够完成的，优先选择`computed`。
2. <font style="color:#DF2A3F;">如果要开启异步任务，只能选择</font>`<font style="color:#DF2A3F;">watch</font>`<font style="color:#DF2A3F;">。</font>因为`computed`依靠`return`。`watch`不需要依赖`return`。

**比较大小的案例：延迟3s出现结果**

```javascript
watch: {
  // 监视num1
  num1: {
    immediate: true,
    handler(val) {
      let result = val - this.num2;
      // 需求2:3s后出现比较结果
      //  此时使用箭头函数，箭头函数没有this，会向上找到num1，num1是vm的属性，
      //   如果将此时箭头函数转成普通函数，this就会是window
      setTimeout(() => {
        if (result == 0) {
          this.compareResult = val + " = " + this.num2;
        } else if (result > 0) {
          this.compareResult = val + " > " + this.num2;
        } else {
          this.compareResult = val + " < " + this.num2;
        }
      }, 3000);
    },
  },
  // 监视num2
  num2: {
    immediate: true,
    handler(val) {
      let result = this.num1 - val;
      setTimeout(() => {
        if (result == 0) {
          this.compareResult = this.num1 + " = " + val;
        } else if (result > 0) {
          this.compareResult = this.num1 + " > " + val;
        } else {
          this.compareResult = this.num1 + " < " + val;
        }
      }, 3000);
    },
  },
}
```

```javascript
computed: {
  // 计算属性的简写形式
  // 计算结果3s后显示，由于setTimeout是异步的，是有js引擎调用的，所以它的this是window，可以使用箭头函数
  compareResult() {
    setTimeout(() => {
      let result = this.num1 - this.num2;
      if (result == 0) {
        return this.num1 + " = " + this.num2;
      } else if (result > 0) {
        return this.num1 + " > " + this.num2;
      } else {
        return this.num1 + " < " + this.num2;
      }
    }, 3000);
  }
}
```

### 2.5.7. 关于函数的写法，写普通函数还是箭头函数？
1. 不管写普通函数还是箭头函数，目标是一致的，都是为了让`this`和`vm`相等。
2. 所有Vue管理的函数，建议写成普通函数。
3. 所有不属于Vue管理的函数，例如`setTimeout`的回调函数、`Promise`的回调函数、`AJAX`的回调函数，建议使用箭头函数。

# 第 3 篇：MVVM 与数据代理

# 2.2.1 MVVM分层思想
## 1. MVVM是什么？
+ **M**：Model（模型/数据）  
+ **V**：View（视图）  
+ **VM**：ViewModel（视图模型）：VM是MVVM中的核心部分，起到非常重要的作用。  
+ **MVVM**：是目前前端开发领域非常流行的开发思想，属于一种架构模式。目前前端的大部分主流框架（如Vue、React等）都实现了MVVM思想。

## 2. Vue框架遵循MVVM吗？
虽然Vue没有完全遵循MVVM模型，但其设计受到MVVM的启发，基本符合MVVM思想。

## 3. 为什么要分离Model和View？
如果不分离，使用原生JavaScript开发时，数据改动需要手动操作DOM，代码繁琐。分离后，VM自动处理数据与视图的更新，无需手动操作DOM，开发效率显著提高。

```html
<body>
  <!-- View (V) -->
  <div id="app">
    姓名：<input type="text" v-model="name">
  </div>
  <!-- Vue程序 -->
  <script>
    // ViewModel (VM)
    const vm = new Vue({
      el: '#app',
      // Model (M)
      data: {
        name: 'zhangsan'
      }
    })
  </script>
</body>

```

---

# 2.2.2 Vue实例的属性
通过Vue实例（`vm`）可以访问以下属性：

+ **公开属性**：以`$`开头，供程序员使用。
+ **私有属性**：以`_`开头，供Vue框架内部使用，通常不建议手动操作。
+ **原型属性**：例如`vm.$delete`等。

```html
<body>
  <div id="app">
    <h1>{{msg}}</h1>
  </div>
  <script>
    let dataObj = {
      msg: "Hello Vue!"
    };

    const vm = new Vue({
      el: "#app",
      data: dataObj
    });

    console.log("dataObj的msg", dataObj.msg);
    console.log("vm的msg", vm.msg); // 数据代理机制
  </script>
</body>

```

---

# 2.2.3 `Object.defineProperty()`
## 1. 作用
ES5新增方法，用于给对象新增属性或设置已有属性。

## 2. 语法
```javascript
Object.defineProperty(对象, '属性名', {
  value: 值,          // 属性值
  writable: true,     // 是否可修改
  enumerable: true,   // 是否可遍历
  configurable: true, // 是否可删除
  get: function() {}, // 获取属性时调用
  set: function(val) {} // 设置属性时调用
});
```

## 3. 示例
```javascript
let person = {};
let temp;

Object.defineProperty(person, "name", {
  enumerable: false,
  configurable: false,
  get: function () {
    console.log("getter方法执行了@@@");
    return temp;
  },
  set: function (val) {
    console.log("setter方法执行了@@@", val);
    temp = val;
  }
});
```

---

# 2.2.4 数据代理机制
通过代理对象的属性间接访问目标对象的属性，实现依赖于`Object.defineProperty()`方法。

```javascript
let target = { name: "zhangsan" };
let proxy = {};

Object.defineProperty(proxy, "name", {
  get() {
    console.log("getter方法执行了@@@@");
    return target.name;
  },
  set(val) {
    target.name = val;
  }
});
```

---

# 2.2.5 数据代理的属性名要求
1. Vue实例不会对以`_`或`$`开头的属性名进行数据代理。
2. 原因：避免与Vue框架自身的属性名冲突。
3. 在Vue中，`data`对象的属性名不能以`_`或`$`开头。

```html
<body>
  <div id="app">
    <h1>{{msg}}</h1>
  </div>
  <script>
    const vm = new Vue({
      el: "#app",
      data: {
        msg: "Hello Vue!",
        _name: "zhangsan", // 不会做数据代理
        $age: 20 // 不会做数据代理
      }
    });
  </script>
</body>

```

---

# 2.2.6 模拟实现数据代理
简单实现`myvm.name == options.data.name`。

```javascript
class MyVue {
  constructor(options) {
    Object.keys(options.data).forEach((propertyName) => {
      Object.defineProperty(this, propertyName, {
        get() {
          return options.data[propertyName];
        },
        set(val) {
          options.data[propertyName] = val;
        }
      });
    });
  }
}

const myvm = new MyVue({
  data: {
    msg: "Hello Vue!",
    name: "jackson",
    age: 30
  }
});
```

---

# 2.2.7 Vue中的数据代理与数据劫持
## 1. 数据代理
+ Vue将`_data`中的数据通过`Object.defineProperty`代理到`vm`实例上。
+ 通过`getter`和`setter`方法，可以直接操作`_data`中的数据。

## 2. 数据劫持
+ 将`data`中的每个属性通过`Object.defineProperty`改写为响应式数据（`_data`）。
+ 监听数据的读取和修改，触发视图更新。

## 3. 总结
1. 数据劫持：将`data`改写为响应式数据（`_data`）。
2. 数据代理：将`_data`中的数据代理到`vm`实例上，方便直接操作。

步骤：

1. 使用`Object.defineProperty`对`data`进行数据劫持，生成响应式的`_data`。
2. 通过`vm`进行数据代理，方便直接操作`_data`中的数据。

