# 第 9 章：对象与引用

对象是JavaScript的核心数据结构，几乎所有的JavaScript程序都涉及对象的创建、操作和管理。理解对象的引用模型对于编写正确和高效的代码至关重要。

## 9.1 创建对象的多种方式

JavaScript提供了多种创建对象的方式，每种方式都有其特点和适用场景。

### 对象字面量

对象字面量是创建对象最简单直观的方式：

```javascript
/**
 * 对象字面量创建方式
 */
const ObjectLiteralExamples = {
    /**
     * 基本对象字面量
     */
    basicObjectLiteral() {
        console.log('=== 基本对象字面量 ===');
        
        // 最简单的对象
        const emptyObject = {};
        console.log('空对象:', emptyObject);
        
        // 带属性的对象
        const person = {
            name: 'Alice',
            age: 25,
            city: 'Beijing'
        };
        console.log('基本对象:', person);
        
        // 对象中包含方法
        const calculator = {
            value: 0,
            add: function(n) {
                this.value += n;
                return this;
            },
            multiply: function(n) {
                this.value *= n;
                return this;
            },
            getValue: function() {
                return this.value;
            }
        };
        
        const result = calculator.add(5).multiply(3).getValue();
        console.log('计算器结果:', result); // 15
        
        // ES6简化方法定义
        const modernCalc = {
            value: 0,
            add(n) {
                this.value += n;
                return this;
            },
            multiply(n) {
                this.value *= n;
                return this;
            },
            getValue() {
                return this.value;
            }
        };
        
        console.log('现代语法计算:', modernCalc.add(10).multiply(2).getValue());
    },
    
    /**
     * 动态属性名
     */
    dynamicProperties() {
        console.log('=== 动态属性名 ===');
        
        // 计算属性名
        const prefix = 'user';
        const suffix = 'Info';
        
        const obj1 = {
            [prefix + suffix]: 'User Information',
            [`${prefix}Name`]: 'Alice',
            [Symbol('id')]: 123
        };
        
        console.log('动态属性对象:', obj1);
        console.log('访问动态属性:', obj1.userInfo);
        
        // 使用表达式作为属性名
        let counter = 0;
        
        const obj2 = {
            [`prop${++counter}`]: 'first',
            [`prop${++counter}`]: 'second',
            [`prop${++counter}`]: 'third'
        };
        
        console.log('表达式属性名:', obj2);
        
        // 使用函数返回值作为属性名
        function getPropertyName(type) {
            return `${type}_${Date.now()}`;
        }
        
        const obj3 = {
            [getPropertyName('data')]: 'value1',
            [getPropertyName('cache')]: 'value2'
        };
        
        console.log('函数生成的属性名:', Object.keys(obj3));
    },
    
    /**
     * 嵌套对象和数组
     */
    nestedStructures() {
        console.log('=== 嵌套对象和数组 ===');
        
        const complexObject = {
            id: 1,
            name: 'Product',
            details: {
                description: 'A product',
                specifications: {
                    weight: '100g',
                    dimensions: {
                        width: 10,
                        height: 20,
                        depth: 5
                    }
                }
            },
            tags: ['new', 'featured', 'sale'],
            reviews: [
                { user: 'Alice', rating: 5, comment: 'Great!' },
                { user: 'Bob', rating: 4, comment: 'Good' }
            ],
            getFullDescription() {
                return `${this.name}: ${this.details.description}`;
            }
        };
        
        console.log('复杂对象:', complexObject);
        console.log('访问嵌套属性:', complexObject.details.specifications.dimensions.width);
        console.log('数组元素:', complexObject.reviews[0].user);
        console.log('方法调用:', complexObject.getFullDescription());
        
        // 对象展开操作符
        const baseConfig = {
            theme: 'dark',
            language: 'zh-CN'
        };
        
        const userConfig = {
            ...baseConfig,
            username: 'user123',
            language: 'en-US' // 覆盖baseConfig中的language
        };
        
        console.log('合并后的配置:', userConfig);
    }
};

