        };
        
        const accessorCopy = {...objWithAccessors};
        console.log('\nGetter/Setter:');
        console.log('拷贝的value:', accessorCopy.value); // 不会触发getter
        console.log('拷贝有getter?:', Object.getOwnPropertyDescriptor(accessorCopy, 'value'));
