        console.log('新theme:', newState2.user.preferences.theme);
        
        // 不可变数组更新
        const newState3 = {
            ...state,
            posts: state.posts.map(post =>
                post.id === 1
                    ? { ...post, likes: post.likes + 1 }
                    : post
