        console.log('翻倍:', doubled);
        console.log('偶数:', evens);
        console.log('总和:', sum);
    },
    
    /**
     * 箭头函数与传统函数的差异
     */
    comparisonWithTraditional() {
        console.log('=== 箭头函数vs传统函数 ===');
        
        const obj = {
