        // 箭头函数没有arguments对象
        function traditionalArgs() {
            console.log('传统函数arguments:', arguments.length);
            return arguments;
        }
        
        const arrowArgs = (...args) => {
            console.log('箭头函数使用rest参数:', args.length);
            return args;
        };
        
