     */
    functionFactory() {
        console.log('=== 函数工厂 ===');
        
        // 创建验证器工厂
        function createValidator(type) {
            switch (type) {
                case 'email':
                    return function(value) {
                        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                        return {
                            isValid: emailRegex.test(value),
                            message: emailRegex.test(value) ? '邮箱格式正确' : '邮箱格式错误'
                        };
                    };
                    
                case 'phone':
                    return function(value) {
                        const phoneRegex = /^1[3-9]\d{9}$/;
                        return {
                            isValid: phoneRegex.test(value),
