            let row = '';
            for (let j = 1; j <= i; j++) {
                row += `${j}×${i}=${i * j}\t`;
            }
            console.log(row);
        }
        
        // 二维数组处理
        const matrix = [
            [1, 2, 3],
            [4, 5, 6],
            [7, 8, 9]
        ];
        
        console.log('矩阵处理:');
        for (let row = 0; row < matrix.length; row++) {
            for (let col = 0; col < matrix[row].length; col++) {
