        // 查找和统计
        const numbers = [1, 2, 3, 4, 5, 2, 3, 2];
        let count = 0;
        const target = 2;
        
        for (let i = 0; i < numbers.length; i++) {
            if (numbers[i] === target) {
                count++;
            }
        }
        console.log(`数字${target}出现${count}次`);
    }
};

