### 标签语句与多层循环控制

标签语句允许在多层嵌套循环中精确控制break和continue的作用范围：

```javascript
/**
 * 标签语句与多层循环控制
 */
const LabeledStatements = {
    /**
     * 基本标签语法
     */
    basicLabels() {
        console.log('=== 基本标签语法 ===');
        
        // 使用标签控制外层循环
        outer: for (let i = 1; i <= 3; i++) {
            console.log(`外层循环: ${i}`);
            
            for (let j = 1; j <= 3; j++) {
                console.log(`  内层循环: ${j}`);
                
                if (i === 2 && j === 2) {
                    console.log('  触发break outer');
                    break outer; // 跳出外层循环
                }
            }
            
            console.log(`外层循环 ${i} 完成`);
        }
        
        console.log('所有循环结束');
    },
    
    /**
     * 标签continue的使用
     */
    labeledContinue() {
        console.log('=== 标签continue ===');
        
        // 跳过外层循环的当前迭代
        outer: for (let i = 1; i <= 3; i++) {
            console.log(`开始外层循环: ${i}`);
            
            for (let j = 1; j <= 3; j++) {
                console.log(`  内层循环: ${j}`);
                
                if (i === 2 && j === 1) {
                    console.log('  触发continue outer');
                    continue outer; // 跳过外层循环的剩余部分
                }
            }
            
            console.log(`外层循环 ${i} 正常完成`);
        }
    }
};

