## 5.6 JSON 的本质与应用

### JSON 数据格式

JSON（JavaScript Object Notation）是一种轻量级的数据交换格式，基于JavaScript对象语法但独立于编程语言：

```javascript
/**
 * JSON 数据格式规范
 */
const JSONFormat = {
    /**
     * JSON 基本规则
     */
    basicRules() {
        console.log('=== JSON 基本规则 ===');
        
        // JSON支持的数据类型
        const supportedTypes = {
            // 1. 字符串（必须使用双引号）
            string: "hello world",
            
            // 2. 数字（整数或浮点数）
            number: 42,
            float: 3.14,
            scientific: 1.23e10,
            
            // 3. 布尔值
            boolean: true,
            
            // 4. null
            nullValue: null,
            
            // 5. 对象
            object: {
                name: "Alice",
                age: 25
            },
            
            // 6. 数组
            array: [1, 2, 3, "hello", true]
        };
        
        console.log('JSON支持的类型:', JSON.stringify(supportedTypes, null, 2));
        
        // JSON不支持的类型
        console.log('=== JSON 不支持的类型 ===');
        const unsupportedTypes = {
            // undefined会被忽略
            undefinedValue: undefined,
            
            // 函数会被忽略
            functionValue: function() { return 'hello'; },
            
            // Symbol会被忽略
            symbolValue: Symbol('test'),
            
            // 日期对象会被转换为字符串
            dateValue: new Date('2023-01-01'),
            
            // RegExp会被转换为空对象
            regexValue: /pattern/g,
            
            // BigInt不被支持（会抛出错误）
            // bigIntValue: 123n
        };
        
        console.log('包含不支持类型的对象:', JSON.stringify(unsupportedTypes));
    },
    
    /**
     * JSON 语法规范
     */
    syntaxRules() {
        console.log('=== JSON 语法规范 ===');
        
        // 正确的JSON格式
        const validJSON = `{
            "name": "John Doe",
            "age": 30,
            "isActive": true,
            "address": {
                "street": "123 Main St",
                "city": "New York",
                "zipCode": null
            },
            "hobbies": ["reading", "swimming", "coding"],
            "score": 95.5
        }`;
        
        console.log('有效的JSON字符串:');
        console.log(validJSON);
        
        // 常见的JSON格式错误
        const invalidExamples = [
            `{ name: "John" }`,                    // 属性名必须用双引号
            `{ "name": 'John' }`,                  // 值必须用双引号
            `{ "name": "John", }`,                 // 不能有尾随逗号
            `{ "comment": "// 这是注释" }`,        // 不支持注释
            `{ "undefined": undefined }`,          // 不支持undefined
            `{ "function": function(){} }`         // 不支持函数
        ];
        
        console.log('常见的JSON格式错误:');
        invalidExamples.forEach((example, index) => {
            console.log(`${index + 1}. ${example}`);
        });
    }
};

