    /**
     * 数据存储和缓存
     */
    dataStorage() {
        console.log('=== 数据存储和缓存 ===');
        
        /**
         * 本地存储管理器
         */
        class StorageManager {
            /**
             * 存储数据
             * @param {string} key - 存储键
             * @param {*} data - 要存储的数据
             * @param {number} ttl - 过期时间（毫秒），0表示永不过期
             */
            static set(key, data, ttl = 0) {
                const item = {
                    data: data,
                    timestamp: Date.now(),
                    ttl: ttl
                };
                
                try {
                    localStorage.setItem(key, JSON.stringify(item));
                    console.log(`数据已存储: ${key}`);
                } catch (error) {
                    console.error('存储失败:', error.message);
                }
            }
            
            /**
             * 获取数据
             * @param {string} key - 存储键
             * @returns {*} 存储的数据，如果不存在或过期则返回null
             */
            static get(key) {
                try {
                    const itemStr = localStorage.getItem(key);
                    if (!itemStr) return null;
                    
                    const item = JSON.parse(itemStr);
                    
                    // 检查是否过期
                    if (item.ttl > 0 && Date.now() - item.timestamp > item.ttl) {
                        localStorage.removeItem(key);
                        console.log(`数据已过期并删除: ${key}`);
                        return null;
                    }
                    
                    return item.data;
                } catch (error) {
                    console.error('读取失败:', error.message);
                    return null;
                }
            }
            
            /**
             * 删除数据
             * @param {string} key - 存储键
             */
            static remove(key) {
                localStorage.removeItem(key);
                console.log(`数据已删除: ${key}`);
            }
            
            /**
             * 清空所有数据
             */
            static clear() {
                localStorage.clear();
                console.log('所有数据已清空');
            }
        }
        
        // 使用示例
        const userData = {
