## 4.4 最佳实践与代码风格

### 现代JavaScript变量声明规范

#### 1. 优先级原则：const > let > var

```javascript
// ✅ 推荐的声明优先级
const CONFIG = { api: '/api/v1' };     // 优先使用const
let counter = 0;                       // 需要重新赋值时使用let
// var legacy;                         // 避免使用var（除非维护老代码）

/**
 * 实际应用示例
 */
function bestPracticeExample() {
    // 常量配置
    const MAX_RETRY = 3;
    const API_ENDPOINTS = {
        users: '/users',
        posts: '/posts'
    };
    
    // 可变变量
    let currentRetry = 0;
    let isLoading = false;
    
    // 函数内的局部常量
    const processData = (data) => {
        const timestamp = Date.now();
        return { ...data, timestamp };
    };
    
    return { MAX_RETRY, currentRetry, processData };
}
```

#### 2. 块级作用域优先

```javascript
// ✅ 利用块级作用域组织代码
function processItems(items) {
    const results = [];
    
    // 处理有效项目
    {
        const validItems = items.filter(item => item && item.id);
        const processedItems = validItems.map(item => ({
            id: item.id,
            name: item.name || 'Unknown',
            processed: true
        }));
        results.push(...processedItems);
    }
    
    // 处理无效项目
    {
        const invalidItems = items.filter(item => !item || !item.id);
        const errorItems = invalidItems.map((item, index) => ({
            error: 'Invalid item',
            index,
            original: item
        }));
        results.push(...errorItems);
    }
    
    return results;
}
```

