### 常见陷阱与避免方法

#### 1. 循环中的变量绑定

```javascript
// ❌ 经典陷阱：循环中的var
function createButtonHandlers_Bad() {
    const buttons = document.querySelectorAll('.btn');
    
    for (var i = 0; i < buttons.length; i++) {
        buttons[i].onclick = function() {
            console.log('点击了按钮', i); // 总是输出最后一个i的值
        };
    }
}

// ✅ 解决方案1：使用let
function createButtonHandlers_Good1() {
    const buttons = document.querySelectorAll('.btn');
    
    for (let i = 0; i < buttons.length; i++) {
        buttons[i].onclick = function() {
            console.log('点击了按钮', i); // 正确输出对应的i值
        };
    }
}

// ✅ 解决方案2：使用forEach
function createButtonHandlers_Good2() {
    const buttons = document.querySelectorAll('.btn');
    
    buttons.forEach((button, index) => {
        button.onclick = () => {
            console.log('点击了按钮', index);
        };
    });
}
```

#### 2. 意外的全局变量

```javascript
// ❌ 意外创建全局变量
function processData_Bad() {
    data = []; // 忘记声明，创建了全局变量
    
    for (item of items) { // 忘记声明，item成为全局变量
        data.push(processItem(item));
    }
    
    return data;
}

// ✅ 正确的变量声明
function processData_Good() {
    'use strict'; // 使用严格模式防止意外全局变量
    
    const data = [];
    
    for (const item of items) {
        data.push(processItem(item));
    }
    
    return data;
}
```

#### 3. 变量提升混淆

```javascript
// ❌ 容易混淆的变量提升
function confusingHoisting_Bad() {
    console.log(message); // undefined，令人困惑
    
    if (false) {
        var message = 'This will never execute';
    }
    
    console.log(message); // 仍然是undefined
}

// ✅ 清晰的变量声明
function clearDeclaration_Good() {
    let message;
    
    if (someCondition()) {
        message = 'Condition is true';
    } else {
        message = 'Condition is false';
    }
    
    console.log(message); // 逻辑清晰
}
```

#### 4. const的误用

```javascript
// ❌ 对const的误解
const users = [];
users = []; // TypeError: Assignment to constant variable

const config = { api: '/api/v1' };
config = {}; // TypeError: Assignment to constant variable

// ✅ 正确使用const
const users = [];
users.push({ id: 1, name: 'Alice' }); // ✅ 可以修改数组内容

const config = { api: '/api/v1' };
config.timeout = 5000; // ✅ 可以修改对象属性

// 如需真正不可变，使用Object.freeze()
const immutableConfig = Object.freeze({
    api: '/api/v1',
    version: '1.0.0'
});
```

