/**
 * Mock响应中间件
 */
const mockResponseMiddleware = (options = {}) => {
  const { delay = 0, errorRate = 0 } = options;
  
  return (req, res, next) => {
    // 模拟网络延迟
    setTimeout(() => {
      // 模拟随机错误
      if (Math.random() < errorRate) {
        return res.status(500).json({ 
          error: 'Internal Server Error',
          code: 'MOCK_ERROR'
        });
      }
      
      next();
    }, delay);
  };
};

// 使用Mock中间件
