### 29.3.3 HTTP模块

```javascript
/**
 * http模块 - HTTP服务器
 */
const http = require('http');
const url = require('url');
const querystring = require('querystring');

// 创建HTTP服务器
const server = http.createServer((req, res) => {
  // 解析URL
  const parsedUrl = url.parse(req.url, true);
  const pathname = parsedUrl.pathname;
  const query = parsedUrl.query;
  
  // 设置响应头
  res.setHeader('Content-Type', 'application/json');
  res.setHeader('Access-Control-Allow-Origin', '*');
  
  console.log(`${req.method} ${pathname}`);
  
  // 路由处理
  if (pathname === '/') {
    res.statusCode = 200;
    res.end(JSON.stringify({ message: 'Hello Node.js' }));
    
  } else if (pathname === '/api/users') {
    handleUsers(req, res, query);
    
  } else if (pathname === '/api/upload' && req.method === 'POST') {
    handleUpload(req, res);
    
  } else {
    res.statusCode = 404;
    res.end(JSON.stringify({ error: 'Not Found' }));
  }
});

// 处理用户API
function handleUsers(req, res, query) {
  const users = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' }
  ];
  
  if (query.id) {
    const user = users.find(u => u.id === parseInt(query.id));
    if (user) {
      res.end(JSON.stringify(user));
    } else {
      res.statusCode = 404;
      res.end(JSON.stringify({ error: 'User not found' }));
    }
  } else {
    res.end(JSON.stringify(users));
  }
}

// 处理文件上传
function handleUpload(req, res) {
  let body = '';
  
  req.on('data', chunk => {
    body += chunk.toString();
  });
  
  req.on('end', () => {
    console.log('接收到数据:', body);
    res.statusCode = 200;
    res.end(JSON.stringify({ message: 'Upload successful' }));
  });
}

// 启动服务器
const PORT = 3000;
server.listen(PORT, () => {
  console.log(`服务器运行在 http://localhost:${PORT}`);
});

/**
 * HTTP客户端
 */
// 发起HTTP请求
const requestOptions = {
  hostname: 'api.github.com',
  port: 443,
  path: '/users/octocat',
  method: 'GET',
  headers: {
    'User-Agent': 'Node.js'
  }
};

const req = http.request(requestOptions, (res) => {
  let data = '';
  
  res.on('data', chunk => {
    data += chunk;
  });
  
  res.on('end', () => {
    console.log('响应数据:', JSON.parse(data));
  });
});

req.on('error', (error) => {
  console.error('请求失败:', error);
});

req.end();
```

