## 29.4 异步IO机制

### 29.4.1 事件循环

```javascript
/**
 * Node.js事件循环阶段
 */
// 1. Timer阶段 - 执行setTimeout和setInterval回调
// 2. Pending阶段 - 执行系统操作的回调
// 3. Poll阶段 - 获取新的I/O事件
// 4. Check阶段 - 执行setImmediate回调
// 5. Close阶段 - 执行close事件回调

console.log('=== 事件循环演示 ===');

// 同步代码
console.log('1. 同步代码');

// Timer阶段
setTimeout(() => console.log('2. setTimeout'), 0);

// Check阶段
setImmediate(() => console.log('3. setImmediate'));

// 微任务
Promise.resolve().then(() => console.log('4. Promise'));

// nextTick（优先级最高）
process.nextTick(() => console.log('5. nextTick'));

console.log('6. 同步代码结束');

/**
 * 微任务 vs 宏任务
 */
// 微任务：process.nextTick, Promise.then
// 宏任务：setTimeout, setImmediate, I/O操作

setTimeout(() => {
  console.log('宏任务1');
  Promise.resolve().then(() => console.log('微任务1'));
}, 0);

setTimeout(() => {
  console.log('宏任务2');
  Promise.resolve().then(() => console.log('微任务2'));
}, 0);

Promise.resolve().then(() => {
  console.log('微任务3');
  setTimeout(() => console.log('宏任务3'), 0);
});
```

### 29.4.2 异步编程模式

```javascript
/**
 * 回调模式
 */
const fs = require('fs');

// 错误优先回调
fs.readFile('example.txt', 'utf8', (err, data) => {
  if (err) {
    console.error('读取失败:', err);
    return;
  }
  console.log('文件内容:', data);
});

/**
 * Promise模式
 */
const { promisify } = require('util');
const readFilePromise = promisify(fs.readFile);

readFilePromise('example.txt', 'utf8')
  .then(data => {
    console.log('文件内容:', data);
  })
  .catch(err => {
    console.error('读取失败:', err);
  });

/**
 * async/await模式
 */
async function readFileAsync() {
  try {
    const data = await readFilePromise('example.txt', 'utf8');
    console.log('文件内容:', data);
  } catch (error) {
    console.error('读取失败:', error);
  }
}

/**
 * Stream流处理
 */
const readableStream = fs.createReadStream('large-file.txt', {
  encoding: 'utf8',
  highWaterMark: 1024 // 1KB缓冲区
});

readableStream.on('data', chunk => {
  console.log('接收到数据块:', chunk.length);
});

readableStream.on('end', () => {
  console.log('文件读取完成');
});

readableStream.on('error', err => {
  console.error('读取错误:', err);
});

/**
 * EventEmitter事件模式
 */
const EventEmitter = require('events');

class MyEmitter extends EventEmitter {}
const myEmitter = new MyEmitter();

// 监听事件
myEmitter.on('data', (message) => {
  console.log('收到消息:', message);
});

// 触发事件
myEmitter.emit('data', 'Hello Events!');

// 一次性监听器
myEmitter.once('special', () => {
  console.log('这只会执行一次');
});
```

