## 27.2 开发服务器与HMR

### 27.2.1 开发服务器配置

```javascript
/**
 * vite.config.js基础配置
 */
import { defineConfig } from 'vite';
import vue from '@vitejs/plugin-vue';

export default defineConfig({
  // 插件配置
  plugins: [vue()],
  
  // 开发服务器配置
  server: {
    port: 3000,        // 端口号
    open: true,        // 自动打开浏览器
    cors: true,        // 允许跨域
    
    // 代理配置
    proxy: {
      '/api': {
        target: 'http://localhost:8080',
        changeOrigin: true,
        rewrite: (path) => path.replace(/^\/api/, '')
      }
    },
    
    // 预热文件
    warmup: {
      clientFiles: ['./src/components/*.vue']
    }
  },
  
  // 路径解析
