### 27.2.2 热模块替换(HMR)

```javascript
/**
 * HMR API使用
 */
// main.js
import { createApp } from 'vue';
import App from './App.vue';

const app = createApp(App);

// HMR处理
if (import.meta.hot) {
  import.meta.hot.accept('./App.vue', (newModule) => {
    // 更新应用
    app.unmount();
    createApp(newModule.default).mount('#app');
  });
  
  // 处理状态保持
  import.meta.hot.accept((newModule) => {
    // 保持应用状态
    location.reload();
  });
  
  // 自定义HMR处理
  import.meta.hot.accept('./utils.js', (newModule) => {
    console.log('Utils模块已更新');
  });
}

/**
 * Vue组件的HMR
 */
// App.vue
<template>
  <div class="app">
    <h1>{{ title }}</h1>
    <Counter :initial="count" />
  </div>
</template>

<script>
export default {
  data() {
    return {
      title: 'Vite App',
      count: 0
    };
  }
};

// HMR状态保持
if (import.meta.hot) {
  let prevData = null;
  
  import.meta.hot.accept();
  
  // 保持组件状态
  if (import.meta.hot.data.prevData) {
    this.$data = import.meta.hot.data.prevData;
  }
  
  import.meta.hot.dispose(() => {
    import.meta.hot.data.prevData = this.$data;
  });
}
</script>

/**
 * CSS HMR
 */
// styles.css更新时自动应用新样式
.app {
  color: red; /* 修改后立即生效 */
}
```

