    name: 'Object',
    method: function() {
        console.log('Method this:', this.name); // 'Object'
        
        function inner() {
            console.log('Inner this:', this); // window/global（非严格模式）
        }
        
        inner(); // 独立调用，使用默认绑定
    }
};

obj.method();
