### 24.5.1 回调函数中的this丢失

```javascript
/**
 * 常见的this丢失场景
 */
class Counter {
    constructor() {
        this.count = 0;
    }
    
    increment() {
        this.count++;
        console.log('Count:', this.count);
    }
    
    setupTimer() {
        // 错误：this丢失
        setTimeout(this.increment, 1000); // undefined
        
        // 解决方案1：bind
        setTimeout(this.increment.bind(this), 2000);
        
        // 解决方案2：箭头函数
        setTimeout(() => this.increment(), 3000);
        
        // 解决方案3：保存this引用
        var self = this;
        setTimeout(function() {
            self.increment();
        }, 4000);
    }
}

var counter = new Counter();
counter.setupTimer();

/**
 * 数组方法回调中的this
 */
var processor = {
    multiplier: 2,
    
    processArray: function(numbers) {
        // 错误：forEach回调中this丢失
        numbers.forEach(function(num) {
            console.log(num * this.multiplier); // NaN
        });
        
        // 解决方案1：传递thisArg参数
        numbers.forEach(function(num) {
            console.log(num * this.multiplier);
        }, this);
        
        // 解决方案2：箭头函数
        numbers.forEach(num => {
            console.log(num * this.multiplier);
        });
    }
};

processor.processArray([1, 2, 3]);
