    let count = 0;
    
    return {
        increment() {
            // 查找 count：当前作用域 -> createCounter 作用域
            count++;
            return count;
        },
        
        decrement() {
            count--;
            return count;
        },
        
        getCount() {
            return count;
        }
    };
}

const counter = createCounter();
