 */
function complexScopeChain() {
    var a = 1;
    var b = 2;
    
    function middle() {
        var b = 20; // 遮蔽外层的 b
        var c = 3;
        
        function inner() {
            var c = 30; // 遮蔽中间层的 c
            var d = 4;
            
            console.log('作用域链查找结果:');
            console.log('a:', a); // 1（来自 complexScopeChain）
            console.log('b:', b); // 20（来自 middle，遮蔽了外层的 2）
            console.log('c:', c); // 30（来自 inner，遮蔽了中间的 3）
            console.log('d:', d); // 4（来自 inner）
        }
        
        inner();
    }
    
    middle();
}

complexScopeChain();
