### 23.3.3 作用域链与性能

```javascript
/**
 * 作用域链查找对性能的影响
 */

// 性能较差的例子：深层作用域链查找
function deepScopeChain() {
    var global = window || global;
    
    function level1() {
        function level2() {
            function level3() {
                function level4() {
                    // 每次查找 global 都需要遍历整个作用域链
                    for (let i = 0; i < 1000000; i++) {
                        global.console; // 深层查找
                    }
                }
                level4();
            }
            level3();
        }
        level2();
    }
    level1();
}

// 性能优化：缓存外层变量
function optimizedScopeChain() {
    var global = window || global;
    
    function level1() {
        function level2() {
            function level3() {
                function level4() {
                    // 将经常使用的外层变量缓存到当前作用域
                    var console = global.console;
                    
                    for (let i = 0; i < 1000000; i++) {
                        console; // 本地查找，更快
                    }
                }
                level4();
            }
            level3();
        }
        level2();
    }
    level1();
}

/**
 * 作用域链优化实践
 */
function scopeOptimization() {
    // 1. 缓存全局变量
    var doc = document;
    var win = window;
    
    // 2. 缓存深层属性
    var body = doc.body;
    var style = body.style;
    
    // 3. 在循环中避免重复查找
    for (let i = 0; i < 100; i++) {
        // 差的做法
        // document.body.style.display = 'none';
        
        // 好的做法
        style.display = i % 2 ? 'block' : 'none';
    }
}

/**
 * 闭包与作用域链的关系
 */
function closureAndScope() {
    var outerVar = 'outer';
    
    function createClosure() {
        var middleVar = 'middle';
        
        return function() {
            var innerVar = 'inner';
            
            // 闭包保持了完整的作用域链
            return {
                inner: innerVar,    // 当前作用域
                middle: middleVar,  // 外层作用域
                outer: outerVar     // 更外层作用域
            };
        };
    }
    
    var closure = createClosure();
    return closure;
}

var myClosure = closureAndScope();
console.log(myClosure()); // { inner: 'inner', middle: 'middle', outer: 'outer' }
