### 23.4.2 闭包的内存管理

```javascript
/**
 * 闭包与垃圾回收
 */

function memoryManagement() {
    var largeData = new Array(1000000).fill('data'); // 大量数据
    var smallData = 'small';
    
    return function() {
        // 只使用 smallData，但 largeData 也不会被回收
        // 因为整个外部函数的变量环境被保持
        return smallData;
    };
}

// 优化版本：只保留需要的变量
function optimizedMemoryManagement() {
    var largeData = new Array(1000000).fill('data');
    var smallData = 'small';
    
    // 显式清除不需要的大对象
    setTimeout(() => {
        largeData = null; // 帮助垃圾回收
    }, 0);
    
    return function() {
        return smallData;
    };
}

/**
 * 闭包内存泄漏的防范
 */
function preventMemoryLeaks() {
    var element = document.getElementById('button');
    var id = element.id;
    
    element.onclick = function() {
        alert(id);
    };
    
    // 清除对 DOM 元素的引用，防止内存泄漏
    element = null;
}

/**
 * 闭包的正确清理
 */
function createManager() {
    var resources = [];
    var listeners = [];
    
    function addResource(resource) {
        resources.push(resource);
    }
    
    function addListener(element, event, handler) {
        element.addEventListener(event, handler);
        listeners.push({ element, event, handler });
    }
    
    function cleanup() {
        // 清理所有资源
        resources.forEach(resource => {
            if (resource.cleanup) {
                resource.cleanup();
            }
        });
        
        // 清理所有事件监听器
        listeners.forEach(({ element, event, handler }) => {
            element.removeEventListener(event, handler);
        });
        
        // 清空数组
        resources.length = 0;
        listeners.length = 0;
    }
    
    return {
        addResource,
        addListener,
        cleanup
    };
}
```

### 23.4.3 闭包的高级应用

```javascript
/**
 * 模块模式
 */
var Module = (function() {
    // 私有变量和方法
    var privateVar = 'I am private';
    var privateCounter = 0;
    
    function privateMethod() {
        return 'Private method called';
    }
    
    // 公共接口
    return {
        publicMethod: function() {
            return privateMethod();
        },
        
        getCounter: function() {
            return privateCounter;
        },
        
        increment: function() {
            return ++privateCounter;
        },
        
        getPrivateVar: function() {
            return privateVar;
        }
    };
})();

console.log(Module.publicMethod()); // 'Private method called'
console.log(Module.increment()); // 1
console.log(Module.getCounter()); // 1

/**
 * 函数工厂
 */
function createValidator(type) {
    var validators = {
        email: function(value) {
            return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
        },
        phone: function(value) {
            return /^\d{10,11}$/.test(value);
        },
        number: function(value) {
            return !isNaN(value) && !isNaN(parseFloat(value));
        }
    };
    
    var validator = validators[type];
    
    if (!validator) {
        throw new Error('Unknown validator type: ' + type);
    }
    
    return function(value) {
        var result = validator(value);
        console.log(`Validating ${type}: ${value} -> ${result}`);
        return result;
    };
}

var emailValidator = createValidator('email');
var phoneValidator = createValidator('phone');

console.log(emailValidator('test@example.com')); // true
console.log(phoneValidator('1234567890')); // true

/**
 * 柯里化实现
 */
function curry(fn) {
    return function curried(...args) {
        if (args.length >= fn.length) {
            return fn.apply(this, args);
        } else {
            return function(...nextArgs) {
                return curried.apply(this, args.concat(nextArgs));
            };
        }
    };
}

function add(a, b, c) {
    return a + b + c;
}

var curriedAdd = curry(add);

console.log(curriedAdd(1)(2)(3)); // 6
console.log(curriedAdd(1, 2)(3)); // 6
console.log(curriedAdd(1)(2, 3)); // 6

/**
 * 防抖和节流
 */
function debounce(func, delay) {
    var timeoutId;
    
    return function(...args) {
        clearTimeout(timeoutId);
        timeoutId = setTimeout(() => {
            func.apply(this, args);
        }, delay);
    };
}

function throttle(func, delay) {
    var lastExecTime = 0;
    
    return function(...args) {
        var currentTime = Date.now();
        
        if (currentTime - lastExecTime > delay) {
            func.apply(this, args);
            lastExecTime = currentTime;
        }
    };
}

// 使用示例
var debouncedLog = debounce(console.log, 300);
var throttledLog = throttle(console.log, 300);
