### 22.1.2 模块化发展历程

```javascript
/**
 * 模块化演进过程
 */

// 1. 立即执行函数（IIFE）
(function(global) {
    var privateVar = 'private';
    
    function privateFunction() {
        return 'This is private';
    }
    
    global.MyModule = {
        publicMethod: function() {
            return privateFunction() + ' but this is public';
        }
    };
})(window);

// 2. 命名空间模式
var MyApp = MyApp || {};
MyApp.Utils = {
    format: function(str) {
        return str.toUpperCase();
    }
};

MyApp.User = {
    name: '',
    getName: function() {
        return MyApp.Utils.format(this.name);
    }
};

// 3. 模块模式
var ModulePattern = (function() {
    var counter = 0;
    
    return {
        increment: function() {
            return ++counter;
        },
        decrement: function() {
            return --counter;
        },
        getCount: function() {
            return counter;
        }
    };
})();
