## 22.2 CommonJS

### 22.2.1 CommonJS 基础

```javascript
/**
 * CommonJS 模块定义（Node.js）
 */

// math.js - 导出模块
function add(a, b) {
    return a + b;
}

function subtract(a, b) {
    return a - b;
}

const PI = Math.PI;

// 导出方式1：exports
exports.add = add;
exports.subtract = subtract;
exports.PI = PI;

// 导出方式2：module.exports
module.exports = {
    add,
    subtract,
    PI,
    multiply: function(a, b) {
        return a * b;
    }
};

// main.js - 导入模块
const math = require('./math');
const { add, subtract } = require('./math');

console.log(math.add(5, 3)); // 8
console.log(subtract(5, 3)); // 2
```

### 22.2.2 CommonJS 特点

```javascript
/**
 * CommonJS 的特性演示
 */

// 1. 同步加载
console.log('开始加载模块');
const fs = require('fs'); // 同步加载，会阻塞后续代码
console.log('模块加载完成');

// 2. 缓存机制
// counter.js
let count = 0;
module.exports = {
    increment() {
        return ++count;
    },
    getCount() {
        return count;
    }
};

// main.js
const counter1 = require('./counter');
const counter2 = require('./counter');

console.log(counter1 === counter2); // true，同一个对象
counter1.increment();
console.log(counter2.getCount()); // 1，共享状态

// 3. 运行时加载
const moduleName = process.argv[2] || 'default';
const dynamicModule = require(`./${moduleName}`); // 动态加载

// 4. 值的拷贝
// utils.js
let count = 0;
module.exports = {
    count,
    increment() {
        count++;
    }
};

// main.js
const { count, increment } = require('./utils');
console.log(count); // 0
increment();
console.log(count); // 仍然是 0，因为是值拷贝
