    this.age = age;
}

PersonFunc.prototype.introduce = function() {
    return `我是${this.name}，今年${this.age}岁`;
};

/**
 * ES6 class 方式（等价实现）
 */
class PersonClass {
    constructor(name, age) {
        this.name = name;
        this.age = age;
    }
    
    introduce() {
        return `我是${this.name}，今年${this.age}岁`;
