}

// 两种方式创建的对象功能相同
const p1 = new PersonFunc('李四', 30);
const p2 = new PersonClass('王五', 30);

console.log(p1.introduce === p1.__proto__.introduce); // true
console.log(p2.introduce === p2.__proto__.introduce); // true
