## 21.4 私有属性

### 21.4.1 私有字段（Private Fields）

```javascript
/**
 * ES2022 私有字段语法
 */
class BankAccount {
    // 私有字段
    #balance = 0;
    #accountNumber;
    
    constructor(accountNumber, initialBalance = 0) {
        this.#accountNumber = accountNumber;
        this.#balance = initialBalance;
    }
    
    // 公共方法访问私有字段
    deposit(amount) {
        if (amount > 0) {
            this.#balance += amount;
            return this.#balance;
        }
        throw new Error('存款金额必须大于0');
    }
    
    withdraw(amount) {
        if (amount <= 0) {
            throw new Error('取款金额必须大于0');
        }
        if (amount > this.#balance) {
            throw new Error('余额不足');
        }
        this.#balance -= amount;
        return this.#balance;
    }
    
    get balance() {
        return this.#balance;
    }
    
    get accountInfo() {
        return `账户: ${this.#accountNumber}, 余额: ${this.#balance}`;
    }
}

const account = new BankAccount('001', 1000);
console.log(account.balance); // 1000
account.deposit(500);
console.log(account.accountInfo); // 账户: 001, 余额: 1500

