### 21.5.3 构造者模式

```javascript
/**
 * 构造者模式实现
 */
class QueryBuilder {
    constructor() {
        this.reset();
    }
    
    reset() {
        this.query = {
            select: [],
            from: '',
            where: [],
            orderBy: [],
            limit: null
        };
        return this;
    }
    
    select(...fields) {
        this.query.select.push(...fields);
        return this;
    }
    
    from(table) {
        this.query.from = table;
        return this;
    }
    
    where(condition) {
        this.query.where.push(condition);
        return this;
    }
    
    orderBy(field, direction = 'ASC') {
        this.query.orderBy.push(`${field} ${direction}`);
        return this;
    }
    
    limit(count) {
        this.query.limit = count;
        return this;
    }
    
    build() {
        const parts = [];
        
        // SELECT
        if (this.query.select.length > 0) {
            parts.push(`SELECT ${this.query.select.join(', ')}`);
        } else {
            parts.push('SELECT *');
        }
        
        // FROM
        if (this.query.from) {
            parts.push(`FROM ${this.query.from}`);
        }
        
        // WHERE
        if (this.query.where.length > 0) {
            parts.push(`WHERE ${this.query.where.join(' AND ')}`);
        }
        
        // ORDER BY
        if (this.query.orderBy.length > 0) {
            parts.push(`ORDER BY ${this.query.orderBy.join(', ')}`);
        }
        
        // LIMIT
        if (this.query.limit) {
            parts.push(`LIMIT ${this.query.limit}`);
        }
        
        return parts.join(' ');
    }
}

// 使用构造者模式
const sql = new QueryBuilder()
    .select('id', 'name', 'email')
    .from('users')
    .where('age > 18')
    .where('status = "active"')
    .orderBy('name')
    .limit(10)
    .build();

console.log(sql);
// SELECT id, name, email FROM users WHERE age > 18 AND status = "active" ORDER BY name LIMIT 10
```

