## 20.4 典型使用场景

### 20.4.1 数据去重与集合运算

```javascript
/**
 * 复杂数据结构去重
 */

// 对象数组去重（基于特定属性）
function uniqueByProperty(arr, prop) {
    const seen = new Set();
    return arr.filter(item => {
        const value = item[prop];
        if (seen.has(value)) {
            return false;
        }
        seen.add(value);
        return true;
    });
}

const users = [
    { id: 1, name: '张三' },
    { id: 2, name: '李四' },
    { id: 1, name: '张三（重复）' },
    { id: 3, name: '王五' }
];

const uniqueUsers = uniqueByProperty(users, 'id');
console.log(uniqueUsers);
// [{ id: 1, name: '张三' }, { id: 2, name: '李四' }, { id: 3, name: '王五' }]

// 多条件去重
function uniqueByMultipleProps(arr, ...props) {
    const seen = new Set();
    return arr.filter(item => {
        const key = props.map(prop => item[prop]).join('|');
        if (seen.has(key)) {
            return false;
        }
        seen.add(key);
        return true;
    });
}
```

### 20.4.2 缓存与记忆化

```javascript
/**
 * 使用 Map 实现函数记忆化
 */
function memoize(fn) {
    const cache = new Map();
    
    return function(...args) {
        const key = JSON.stringify(args);
        
        if (cache.has(key)) {
            console.log('从缓存获取结果');
            return cache.get(key);
        }
        
        console.log('计算新结果');
        const result = fn.apply(this, args);
        cache.set(key, result);
        return result;
    };
}

// 斐波那契数列（带缓存）
const fibonacci = memoize(function(n) {
    if (n <= 1) return n;
    return fibonacci(n - 1) + fibonacci(n - 2);
});

console.log(fibonacci(10)); // 计算新结果...
console.log(fibonacci(10)); // 从缓存获取结果

/**
 * LRU 缓存实现
 */
class LRUCache {
    constructor(capacity) {
        this.capacity = capacity;
        this.cache = new Map();
    }
    
    get(key) {
        if (this.cache.has(key)) {
            // 重新插入以更新顺序（LRU）
            const value = this.cache.get(key);
            this.cache.delete(key);
            this.cache.set(key, value);
            return value;
        }
        return -1;
    }
    
    put(key, value) {
        if (this.cache.has(key)) {
            this.cache.delete(key);
        } else if (this.cache.size >= this.capacity) {
            // 删除最久未使用的项（第一个）
            const firstKey = this.cache.keys().next().value;
            this.cache.delete(firstKey);
        }
        this.cache.set(key, value);
    }
}
```

### 20.4.3 状态管理与追踪

```javascript
/**
 * 组件状态追踪
 */
const componentStates = new WeakMap();

class Component {
    constructor(name) {
        this.name = name;
        componentStates.set(this, {
            mounted: false,
            updated: 0,
            props: new Map()
        });
    }
    
    mount() {
        const state = componentStates.get(this);
        state.mounted = true;
        console.log(`${this.name} 组件已挂载`);
    }
    
    update() {
        const state = componentStates.get(this);
        state.updated++;
        console.log(`${this.name} 组件已更新 ${state.updated} 次`);
    }
    
    setProp(key, value) {
        const state = componentStates.get(this);
        state.props.set(key, value);
    }
    
    getProp(key) {
        const state = componentStates.get(this);
        return state.props.get(key);
    }
}

/**
 * 事件订阅管理
 */
class EventManager {
    constructor() {
        this.listeners = new Map();
    }
    
    on(event, callback) {
        if (!this.listeners.has(event)) {
            this.listeners.set(event, new Set());
        }
        this.listeners.get(event).add(callback);
    }
    
    off(event, callback) {
        if (this.listeners.has(event)) {
            this.listeners.get(event).delete(callback);
        }
    }
    
    emit(event, data) {
        if (this.listeners.has(event)) {
            this.listeners.get(event).forEach(callback => {
                callback(data);
            });
        }
    }
}
```

### 20.4.4 性能对比与选择建议

```javascript
/**
 * 不同数据结构的性能对比
 */
function performanceTest() {
    const size = 100000;
    
    // 测试 Map vs Object
    console.time('Map 插入');
    const map = new Map();
    for (let i = 0; i < size; i++) {
        map.set(`key${i}`, i);
    }
    console.timeEnd('Map 插入');
    
    console.time('Object 插入');
    const obj = {};
    for (let i = 0; i < size; i++) {
        obj[`key${i}`] = i;
    }
    console.timeEnd('Object 插入');
    
    // 测试查找性能
    console.time('Map 查找');
    for (let i = 0; i < 1000; i++) {
        map.get(`key${Math.floor(Math.random() * size)}`);
    }
    console.timeEnd('Map 查找');
    
    console.time('Object 查找');
    for (let i = 0; i < 1000; i++) {
        obj[`key${Math.floor(Math.random() * size)}`];
    }
    console.timeEnd('Object 查找');
}

// performanceTest();
```

### 20.4.5 选择指南

| 数据结构 | 适用场景 | 优势 | 注意事项 |
|----------|----------|------|----------|
| **Map** | 频繁增删键值对<br>需要非字符串键<br>需要保持插入顺序 | 任意类型键<br>更好的迭代性能<br>size 属性 | 内存占用略高 |
| **Set** | 数据去重<br>成员检测<br>集合运算 | 自动去重<br>快速查找<br>集合操作 | 只存储值 |
| **WeakMap** | 私有数据存储<br>DOM 关联数据<br>避免内存泄漏 | 弱引用<br>垃圾回收友好 | 不可遍历<br>键只能是对象 |
| **WeakSet** | 对象标记<br>循环引用检测<br>临时对象集合 | 弱引用<br>自动清理 | 不可遍历<br>只能存储对象 |

```javascript
/**
 * 选择建议示例
 */

// ✅ 使用 Map：需要复杂键类型
const userCache = new Map();
const userObj = { id: 123 };
userCache.set(userObj, { name: '张三', lastActive: Date.now() });

// ✅ 使用 Set：数据去重
const uniqueIds = new Set([1, 2, 2, 3, 4, 4, 5]);

// ✅ 使用 WeakMap：私有数据
const privateProps = new WeakMap();
class User {
    constructor(name) {
        privateProps.set(this, { name, secret: Math.random() });
    }
}

// ✅ 使用普通 Object：简单的键值存储
const config = {
    apiUrl: 'https://api.example.com',
    timeout: 5000
};
```

