const BestPractices = {
    /**
     * 声明选择原则
     */
    declarationPrinciples() {
        console.log('=== 声明选择原则 ===');
        
        // 原则1: 优先使用const
        const config = {
            apiUrl: 'https://api.example.com',
            timeout: 5000
        };
        
        const users = ['Alice', 'Bob', 'Charlie'];
        
        console.log('优先使用const:', { config, users });
        
        // 原则2: 需要重新赋值时使用let
        let currentUser = null;
        let isLoading = false;
        
        function loginUser(username) {
            isLoading = true;
            
            // 模拟异步登录
            setTimeout(() => {
                currentUser = { username, id: Date.now() };
                isLoading = false;
                console.log('用户登录:', { currentUser, isLoading });
            }, 100);
        }
        
        loginUser('alice');
        
        // 原则3: 避免使用var
        console.log('避免使用var的原因:');
        console.log('- 函数作用域容易产生意外');
        console.log('- 变量提升令人困惑');
        console.log('- 可以重复声明');
    },
    
    /**
     * 模块作用域管理
     */
    moduleScope() {
        console.log('=== 模块作用域管理 ===');
        
        // 模块级常量
        const MODULE_NAME = 'UserManager';
        const API_VERSION = 'v1';
        const MAX_RETRY_COUNT = 3;
        
        // 模块内部状态
        let retryCount = 0;
        let lastError = null;
        
        // 导出的API
        const UserManager = {
            getModuleInfo() {
                return {
                    name: MODULE_NAME,
                    version: API_VERSION,
                    maxRetries: MAX_RETRY_COUNT
                };
            },
            
            async fetchUser(id) {
                try {
                    retryCount = 0; // 重置重试次数
                    
                    // 模拟API调用
                    if (Math.random() > 0.7) {
                        throw new Error('网络错误');
                    }
                    
                    return { id, name: `User${id}` };
                    
                } catch (error) {
                    lastError = error;
                    retryCount++;
                    
                    if (retryCount < MAX_RETRY_COUNT) {
                        console.log(`重试第${retryCount}次`);
                        return this.fetchUser(id);
                    }
                    
                    throw new Error(`获取用户失败，已重试${MAX_RETRY_COUNT}次`);
                }
            },
            
            getStatus() {
                return {
                    retryCount,
                    lastError: lastError?.message
                };
            }
        };
        
        console.log('模块信息:', UserManager.getModuleInfo());
        
        // 测试模块API
        UserManager.fetchUser(123).then(
            user => console.log('获取用户成功:', user),
            error => console.log('获取用户失败:', error.message)
        ).finally(() => {
            console.log('模块状态:', UserManager.getStatus());
        });
    },
    
    /**
     * 块级作用域的实际应用
     */
    practicalBlockScope() {
        console.log('=== 块级作用域实际应用 ===');
        
        // 应用1: 条件性功能初始化
        const features = ['feature1', 'feature2', 'feature3'];
        
        features.forEach(feature => {
            if (feature === 'feature2') {
                const specialConfig = {
                    endpoint: `/api/${feature}`,
                    method: 'POST',
                    headers: { 'X-Special': 'true' }
                };
                
                console.log(`${feature}特殊配置:`, specialConfig);
                // specialConfig只在这个if块中存在
            }
        });
        
        // 应用2: 临时变量作用域限制
        function processData(data) {
            const result = [];
            
            // 数据验证阶段
            {
                const validator = {
                    isValid: (item) => item && typeof item === 'object',
                    hasRequiredFields: (item) => 'id' in item && 'name' in item
                };
                
                data = data.filter(item => 
                    validator.isValid(item) && validator.hasRequiredFields(item)
                );
                
                console.log(`验证后数据量: ${data.length}`);
                // validator只在验证阶段存在
            }
            
            // 数据处理阶段
            {
                const processor = {
                    normalize: (item) => ({
                        ...item,
                        name: item.name.trim().toLowerCase(),
                        processed: true
                    }),
                    addTimestamp: (item) => ({
                        ...item,
                        timestamp: Date.now()
                    })
                };
                
                data.forEach(item => {
                    let processed = processor.normalize(item);
                    processed = processor.addTimestamp(processed);
                    result.push(processed);
                });
                
                console.log('数据处理完成');
                // processor只在处理阶段存在
            }
            
            return result;
        }
        
        const testData = [
            { id: 1, name: '  Alice  ' },
            { id: 2, name: 'Bob' },
            { name: 'Charlie' }, // 缺少id
            { id: 3, name: '  David  ' }
        ];
        
        const processedData = processData(testData);
        console.log('处理结果:', processedData);
    }
};

