            WHERE id = ${userId} 
            AND name = ${userName}
            AND tags IN (${tags})
        `;
        
        queryBuilder.execute();
        
        // 国际化标签函数
        const translations = {
            'en': {
                'hello': 'Hello',
                'welcome': 'Welcome',
                'user': 'User'
            },
            'zh': {
                'hello': '你好',
                'welcome': '欢迎',
                'user': '用户'
            }
        };
        
        let currentLang = 'en';
        
        function i18n(strings, ...keys) {
            return strings.reduce((result, string, index) => {
                const key = keys[index];
                const translation = key ? (translations[currentLang][key] || key) : '';
                return result + string + translation;
            }, '');
