            },
            
            // ES6简写
            add(a, b) {
                return a + b;
            },
            
            // 箭头函数属性
            multiply: (a, b) => a * b,
            
            // 计算属性名
            ['subtract'](a, b) {
                return a - b;
            }
        };
        
        console.log('计算器方法:');
        console.log('加法:', calculator.add(5, 3));
        console.log('乘法:', calculator.multiply(4, 6));
