### 高级配置和错误处理

```javascript
/**
 * Fetch高级配置示例
 */
const FetchAdvanced = {
    /**
     * 请求配置和超时控制
     */
    async advancedConfig() {
        console.log('=== 高级配置 ===');
        
        // 超时控制
        function fetchWithTimeout(url, options = {}, timeout = 5000) {
            return Promise.race([
                fetch(url, options),
                new Promise((_, reject) => 
                    setTimeout(() => reject(new Error('请求超时')), timeout)
                )
            ]);
        }
        
        // AbortController取消请求
        const controller = new AbortController();
        
        // 5秒后取消请求
        setTimeout(() => {
            controller.abort();
            console.log('请求已取消');
        }, 5000);
        
        try {
            const response = await fetch('https://httpbin.org/delay/3', {
                method: 'GET',
                headers: {
                    'Accept': 'application/json',
                    'User-Agent': 'Custom-App/1.0'
                },
                signal: controller.signal, // 绑定取消信号
                cache: 'no-cache', // 缓存策略
                credentials: 'same-origin', // Cookie策略
                redirect: 'follow', // 重定向策略
                referrer: 'no-referrer' // 引用策略
            });
            
            if (!response.ok) {
                throw new Error(`请求失败: ${response.status}`);
            }
            
            const data = await response.json();
            console.log('高级配置响应:', data);
            
        } catch (error) {
            if (error.name === 'AbortError') {
                console.log('请求被用户取消');
            } else {
                console.error('请求错误:', error.message);
            }
        }
    },
    
    /**
     * 响应处理和错误分类
     */
    async responseHandling() {
        console.log('=== 响应处理和错误分类 ===');
        
        // 通用响应处理器
        async function handleResponse(response) {
            const contentType = response.headers.get('Content-Type') || '';
            
            if (contentType.includes('application/json')) {
                return await response.json();
            } else if (contentType.includes('text/')) {
                return await response.text();
            } else if (contentType.includes('application/octet-stream')) {
                return await response.blob();
            } else {
                return await response.arrayBuffer();
            }
        }
        
        // 错误分类处理器
        class HTTPError extends Error {
            constructor(response) {
                super(`HTTP Error: ${response.status} ${response.statusText}`);
                this.response = response;
                this.status = response.status;
            }
        }
        
        async function fetchWithErrorHandling(url, options = {}) {
            try {
                const response = await fetch(url, options);
                
                if (!response.ok) {
                    throw new HTTPError(response);
                }
                
                return await handleResponse(response);
                
            } catch (error) {
                if (error instanceof HTTPError) {
                    // HTTP错误处理
                    switch (error.status) {
                        case 400:
                            console.error('请求参数错误');
                            break;
                        case 401:
                            console.error('未授权访问');
                            break;
                        case 403:
                            console.error('禁止访问');
                            break;
                        case 404:
                            console.error('资源不存在');
                            break;
                        case 500:
                            console.error('服务器内部错误');
                            break;
                        default:
                            console.error('HTTP错误:', error.message);
                    }
                } else if (error.name === 'TypeError') {
                    // 网络错误
                    console.error('网络连接失败');
                } else {
                    // 其他错误
                    console.error('未知错误:', error.message);
                }
                throw error;
            }
        }
        
        // 测试不同错误场景
        const testURLs = [
            'https://jsonplaceholder.typicode.com/posts/1', // 成功
            'https://jsonplaceholder.typicode.com/posts/999', // 404
            'https://invalid-url-that-does-not-exist.com' // 网络错误
        ];
        
        for (const url of testURLs) {
            try {
                await fetchWithErrorHandling(url);
                console.log(`✅ ${url} 请求成功`);
            } catch (error) {
                console.log(`❌ ${url} 请求失败`);
            }
        }
    }
};

