            return [task1, task2, task3];
        }
        
        // 并行执行（高效）
        async function parallelExecution() {
            const startTime = Date.now();
            
            // 同时启动所有Promise
            const promises = [
                new Promise(resolve => setTimeout(() => resolve('任务1'), 300)),
                new Promise(resolve => setTimeout(() => resolve('任务2'), 200)),
