    practicalApplications() {
        console.log('=== 实际应用场景 ===');
        
        // 1. 批量DOM更新优化
        function batchDOMUpdates() {
            console.log('批量DOM更新示例:');
            
            if (typeof document === 'undefined') {
                console.log('需要浏览器环境');
                return;
            }
            
            const div = document.createElement('div');
            div.textContent = '初始内容';
            document.body.appendChild(div);
            
            // 使用微任务批量更新
            Promise.resolve().then(() => {
                div.textContent = '更新1';
                div.style.color = 'red';
                console.log('微任务中更新DOM');
            });
            
            Promise.resolve().then(() => {
                div.style.fontSize = '20px';
                console.log('另一个微任务更新样式');
            });
            
            // 宏任务中的更新会在下一轮
            setTimeout(() => {
                div.textContent = '宏任务更新';
                console.log('宏任务中更新DOM');
            }, 0);
            
            // 清理
            setTimeout(() => {
                if (document.body.contains(div)) {
                    document.body.removeChild(div);
                }
            }, 2000);
        }
        
        // 2. 状态同步管理
        class StateManager {
            constructor() {
                this.state = {};
                this.listeners = [];
                this.updateScheduled = false;
            }
            
            setState(updates) {
                Object.assign(this.state, updates);
                this.scheduleUpdate();
            }
            
            scheduleUpdate() {
                if (!this.updateScheduled) {
                    this.updateScheduled = true;
                    // 使用微任务确保同步更新
                    Promise.resolve().then(() => {
                        this.notifyListeners();
                        this.updateScheduled = false;
                    });
                }
            }
            
            notifyListeners() {
                this.listeners.forEach(listener => {
                    listener(this.state);
                });
            }
            
            subscribe(listener) {
                this.listeners.push(listener);
            }
        }
        
        const stateManager = new StateManager();
        
        stateManager.subscribe((state) => {
            console.log('状态更新:', state);
        });
        
        // 多次快速更新只会触发一次通知
        stateManager.setState({ count: 1 });
        stateManager.setState({ count: 2 });
        stateManager.setState({ count: 3 });
        
        batchDOMUpdates();
        
        // 3. 异步错误处理
        function asyncErrorHandling() {
            console.log('异步错误处理示例:');
            
            // 微任务中的错误
            Promise.resolve().then(() => {
                throw new Error('微任务中的错误');
            }).catch(error => {
                console.log('捕获微任务错误:', error.message);
            });
            
            // 宏任务中的错误
            setTimeout(() => {
                try {
                    throw new Error('宏任务中的错误');
                } catch (error) {
                    console.log('捕获宏任务错误:', error.message);
                }
            }, 0);
        }
        
        asyncErrorHandling();
    }
};

