## 14.2 定时器

JavaScript提供了多种定时器机制，用于延迟执行和周期性执行代码。

### 基础定时器

setTimeout和setInterval的使用：

```javascript
/**
 * 定时器示例
 */
const TimerExamples = {
    /**
     * 基础定时器使用
     */
    basicTimers() {
        console.log('=== 基础定时器 ===');
        
        // setTimeout - 延迟执行
        console.log('设置setTimeout，2秒后执行');
        const timeoutId = setTimeout(() => {
            console.log('setTimeout执行: 2秒已过');
        }, 2000);
        
        // 取消setTimeout
        const cancelTimeoutId = setTimeout(() => {
            console.log('这条消息不会显示');
        }, 5000);
        
        setTimeout(() => {
            clearTimeout(cancelTimeoutId);
            console.log('5秒timeout已取消');
        }, 1000);
        
        // setInterval - 周期性执行
        console.log('设置setInterval，每1秒执行一次');
        let count = 0;
        const intervalId = setInterval(() => {
            count++;
            console.log(`setInterval执行第${count}次`);
            
            // 5次后停止
            if (count >= 5) {
                clearInterval(intervalId);
                console.log('setInterval已停止');
            }
        }, 1000);
        
        // 带参数的定时器
        setTimeout((message, number) => {
            console.log('带参数的定时器:', message, number);
        }, 3000, 'Hello', 42);
        
        console.log('定时器设置完成');
    },
    
    /**
     * 定时器管理
     */
    timerManagement() {
        console.log('=== 定时器管理 ===');
        
        // 定时器管理类
        class TimerManager {
            constructor() {
                this.timers = new Map();
                this.nextId = 1;
            }
            
            // 添加setTimeout
            addTimeout(callback, delay, name = null) {
                const id = this.nextId++;
                const timerId = setTimeout(() => {
                    callback();
                    this.timers.delete(id);
                }, delay);
                
                this.timers.set(id, {
                    type: 'timeout',
                    timerId,
                    name: name || `timeout_${id}`,
                    delay,
                    callback,
                    createdAt: Date.now()
                });
                
                return id;
            }
            
            // 添加setInterval
            addInterval(callback, interval, name = null) {
                const id = this.nextId++;
                const timerId = setInterval(callback, interval);
                
                this.timers.set(id, {
                    type: 'interval',
                    timerId,
                    name: name || `interval_${id}`,
                    interval,
                    callback,
                    createdAt: Date.now()
                });
                
                return id;
            }
            
            // 清除特定定时器
            clear(id) {
                const timer = this.timers.get(id);
                if (timer) {
                    if (timer.type === 'timeout') {
                        clearTimeout(timer.timerId);
                    } else {
                        clearInterval(timer.timerId);
                    }
                    this.timers.delete(id);
                    return true;
                }
                return false;
            }
            
            // 清除所有定时器
            clearAll() {
                for (let [id, timer] of this.timers) {
                    if (timer.type === 'timeout') {
                        clearTimeout(timer.timerId);
                    } else {
                        clearInterval(timer.timerId);
                    }
                }
                this.timers.clear();
            }
            
            // 获取定时器信息
            getInfo() {
                const info = [];
                for (let [id, timer] of this.timers) {
                    info.push({
                        id,
                        name: timer.name,
                        type: timer.type,
                        delay: timer.delay || timer.interval,
                        age: Date.now() - timer.createdAt
                    });
                }
                return info;
            }
            
            // 按名称清除
            clearByName(name) {
                let cleared = 0;
                for (let [id, timer] of this.timers) {
                    if (timer.name === name) {
                        this.clear(id);
                        cleared++;
                    }
                }
                return cleared;
            }
        }
        
        // 使用定时器管理器
        const tm = new TimerManager();
        
        // 添加一些定时器
        const id1 = tm.addTimeout(() => {
            console.log('管理的timeout执行');
        }, 2000, 'test-timeout');
        
        const id2 = tm.addInterval(() => {
            console.log('管理的interval执行');
        }, 1000, 'test-interval');
        
        // 查看定时器信息
        setTimeout(() => {
            console.log('定时器信息:', tm.getInfo());
        }, 1500);
        
        // 5秒后清除所有定时器
        setTimeout(() => {
            tm.clearAll();
            console.log('所有定时器已清除');
        }, 5000);
        
        window.timerManager = tm; // 暴露到全局，方便调试
    },
    
    /**
     * 高精度定时器
     */
    precisionTimers() {
        console.log('=== 高精度定时器 ===');
        
        // requestAnimationFrame - 动画帧
        let frameCount = 0;
        let startTime = performance.now();
        
        function animate(currentTime) {
            frameCount++;
            
            if (frameCount % 60 === 0) { // 每60帧显示一次
                const elapsed = currentTime - startTime;
                const fps = (frameCount / elapsed) * 1000;
                console.log(`帧数: ${frameCount}, FPS: ${fps.toFixed(2)}`);
            }
            
            if (frameCount < 300) { // 运行5秒 (假设60fps)
                requestAnimationFrame(animate);
            } else {
                console.log('动画结束');
            }
        }
        
        console.log('开始requestAnimationFrame动画');
        requestAnimationFrame(animate);
        
        // performance.now() - 高精度时间戳
        const preciseStart = performance.now();
        setTimeout(() => {
            const preciseEnd = performance.now();
            console.log(`精确耗时: ${preciseEnd - preciseStart} 毫秒`);
        }, 100);
        
        // 使用Web Workers的定时器 (如果支持)
        if (typeof Worker !== 'undefined') {
            try {
                // 创建Web Worker用于精确定时
                const workerCode = `
                    let interval;
                    self.onmessage = function(e) {
                        if (e.data.action === 'start') {
                            interval = setInterval(() => {
                                self.postMessage({
                                    type: 'tick',
                                    timestamp: Date.now()
                                });
                            }, e.data.interval);
                        } else if (e.data.action === 'stop') {
                            clearInterval(interval);
                        }
                    };
                `;
                
                const blob = new Blob([workerCode], { type: 'application/javascript' });
                const worker = new Worker(URL.createObjectURL(blob));
                
                let tickCount = 0;
                worker.onmessage = (e) => {
                    if (e.data.type === 'tick') {
                        tickCount++;
                        if (tickCount <= 5) {
                            console.log(`Worker定时器tick ${tickCount}:`, e.data.timestamp);
                        }
                        
                        if (tickCount >= 10) {
                            worker.postMessage({ action: 'stop' });
                            worker.terminate();
                        }
                    }
                };
                
                worker.postMessage({ action: 'start', interval: 500 });
                console.log('Web Worker定时器已启动');
                
            } catch (e) {
                console.log('Web Worker不可用:', e.message);
            }
        }
    }
};

