## 14.4 localStorage / sessionStorage / cookie

Web存储机制的完整应用。

### 本地存储机制

```javascript
/**
 * 存储管理示例
 */
const StorageExamples = {
    /**
     * localStorage操作
     */
    localStorageOperations() {
        console.log('=== localStorage操作 ===');
        
        if (typeof localStorage === 'undefined') return;
        
        // 基础操作
        localStorage.setItem('username', 'Alice');
        localStorage.setItem('preferences', JSON.stringify({
            theme: 'dark',
            language: 'zh-CN'
        }));
        
        console.log('存储数据:');
        console.log('username:', localStorage.getItem('username'));
        
        const prefs = JSON.parse(localStorage.getItem('preferences') || '{}');
        console.log('preferences:', prefs);
        
        // 遍历localStorage
        console.log('所有localStorage数据:');
        for (let i = 0; i < localStorage.length; i++) {
            const key = localStorage.key(i);
            const value = localStorage.getItem(key);
            console.log(`  ${key}: ${value}`);
        }
        
        // 删除操作
        localStorage.removeItem('username');
        console.log('删除username后length:', localStorage.length);
    },
    
    /**
     * 存储管理类
     */
    storageManager() {
        console.log('=== 存储管理类 ===');
        
        class StorageManager {
            constructor(storage = localStorage) {
                this.storage = storage;
            }
            
            // 设置值（自动JSON序列化）
            set(key, value, expiry = null) {
                const data = {
                    value: value,
                    timestamp: Date.now(),
                    expiry: expiry ? Date.now() + expiry : null
                };
                
                try {
                    this.storage.setItem(key, JSON.stringify(data));
                    return true;
                } catch (e) {
                    console.error('存储失败:', e);
                    return false;
                }
            }
            
            // 获取值（自动JSON反序列化）
            get(key, defaultValue = null) {
                try {
                    const item = this.storage.getItem(key);
                    if (!item) return defaultValue;
                    
                    const data = JSON.parse(item);
                    
                    // 检查过期时间
                    if (data.expiry && Date.now() > data.expiry) {
                        this.remove(key);
                        return defaultValue;
                    }
                    
                    return data.value;
                } catch (e) {
                    console.error('读取失败:', e);
                    return defaultValue;
                }
            }
            
            // 删除键
            remove(key) {
                this.storage.removeItem(key);
            }
            
            // 清空所有数据
            clear() {
                this.storage.clear();
            }
            
            // 获取所有键
            keys() {
                const keys = [];
                for (let i = 0; i < this.storage.length; i++) {
                    keys.push(this.storage.key(i));
                }
                return keys;
            }
            
            // 获取存储大小估算
            getSize() {
                let total = 0;
                for (let key in this.storage) {
                    if (this.storage.hasOwnProperty(key)) {
                        total += this.storage[key].length + key.length;
                    }
                }
                return total;
            }
            
            // 清理过期数据
            cleanup() {
                const now = Date.now();
                const keysToRemove = [];
                
                for (let i = 0; i < this.storage.length; i++) {
                    const key = this.storage.key(i);
                    try {
                        const data = JSON.parse(this.storage.getItem(key));
                        if (data.expiry && now > data.expiry) {
                            keysToRemove.push(key);
                        }
                    } catch (e) {
                        // 忽略解析错误的数据
                    }
                }
                
                keysToRemove.forEach(key => this.remove(key));
                return keysToRemove.length;
            }
        }
        
        // 使用示例
        const storage = new StorageManager();
        
        storage.set('user', { name: 'Bob', age: 30 });
        storage.set('temp', 'temporary data', 5000); // 5秒后过期
        
        console.log('存储的用户:', storage.get('user'));
        console.log('存储大小:', storage.getSize(), 'bytes');
        
        setTimeout(() => {
            console.log('5秒后temp值:', storage.get('temp', 'expired'));
            console.log('清理过期数据:', storage.cleanup(), '个');
        }, 6000);
        
        window.storageManager = storage; // 暴露到全局
    }
};

