            mouseArea.style.backgroundColor = 'lightblue';
        });
        
        mouseArea.addEventListener('click', (event) => {
            updateInfo(`点击: (${event.offsetX}, ${event.offsetY})`);
        });
        
        mouseArea.addEventListener('dblclick', (event) => {
            updateInfo('双击事件');
            mouseArea.style.backgroundColor = 'yellow';
            setTimeout(() => {
                mouseArea.style.backgroundColor = 'lightblue';
            }, 200);
