### 遍历算法

高效的DOM树遍历方法：

```javascript
/**
 * DOM遍历算法示例
 */
const TraversalAlgorithms = {
    /**
     * 深度优先遍历
     */
    depthFirstTraversal() {
        console.log('=== 深度优先遍历 ===');
        
        if (typeof document === 'undefined') return;
        
        // 递归深度优先
        function dfsRecursive(node, callback, level = 0) {
            if (!node) return;
            
            callback(node, level);
            
            for (let child of node.children) {
                dfsRecursive(child, callback, level + 1);
            }
        }
        
        // 迭代深度优先
        function dfsIterative(root, callback) {
            if (!root) return;
            
            const stack = [{node: root, level: 0}];
            
            while (stack.length > 0) {
                const {node, level} = stack.pop();
                callback(node, level);
                
                // 子节点逆序入栈保持正确顺序
                const children = Array.from(node.children);
                for (let i = children.length - 1; i >= 0; i--) {
                    stack.push({node: children[i], level: level + 1});
                }
            }
        }
        
        // 测试遍历
        if (document.body.children.length > 0) {
            console.log('递归深度优先遍历:');
            dfsRecursive(document.body, (node, level) => {
                const indent = '  '.repeat(level);
                console.log(`${indent}${node.tagName}`);
            });
        }
    },
    
    /**
     * 广度优先遍历
     */
    breadthFirstTraversal() {
        console.log('=== 广度优先遍历 ===');
        
        if (typeof document === 'undefined') return;
        
        function bfs(root, callback) {
            if (!root) return;
            
            const queue = [{node: root, level: 0}];
            
            while (queue.length > 0) {
                const {node, level} = queue.shift();
                callback(node, level);
                
                for (let child of node.children) {
                    queue.push({node: child, level: level + 1});
                }
            }
        }
        
        // 按层级分组遍历
        function bfsByLevel(root) {
            if (!root) return [];
            
            const levels = [];
            const queue = [{node: root, level: 0}];
            
            while (queue.length > 0) {
                const {node, level} = queue.shift();
                
                if (!levels[level]) {
                    levels[level] = [];
                }
                levels[level].push(node);
                
                for (let child of node.children) {
                    queue.push({node: child, level: level + 1});
                }
            }
            
            return levels;
        }
        
        console.log('广度优先遍历功能已定义');
    },
    
    /**
     * 条件查找遍历
     */
    conditionalTraversal() {
        console.log('=== 条件查找遍历 ===');
        
        if (typeof document === 'undefined') return;
        
        // 查找满足条件的第一个元素
        function findElement(root, predicate) {
            if (!root) return null;
            
            if (predicate(root)) return root;
            
            for (let child of root.children) {
                const result = findElement(child, predicate);
                if (result) return result;
            }
            
            return null;
        }
        
        // 查找所有满足条件的元素
        function findAllElements(root, predicate) {
            const results = [];
            
            function traverse(node) {
                if (!node) return;
                
                if (predicate(node)) {
                    results.push(node);
                }
                
                for (let child of node.children) {
                    traverse(child);
                }
            }
            
            traverse(root);
            return results;
        }
        
        // 查找路径
        function findPath(root, target) {
            function findPathRecursive(node, path) {
                if (!node) return null;
                
                path.push(node);
                
                if (node === target) {
                    return path.slice();
                }
                
                for (let child of node.children) {
                    const result = findPathRecursive(child, path);
                    if (result) return result;
                }
                
                path.pop();
                return null;
            }
            
            return findPathRecursive(root, []);
        }
        
        console.log('条件查找功能已定义');
    }
};

