        }));
        
        console.log('增加奖金和类别:', withBonus);
        
        // 重构数据结构
        const userMap = users.map(user => ({
            [`user_${user.id}`]: {
                profile: { name: user.name, age: user.age },
                employment: { salary: user.salary }
            }
        }));
        
        console.log('重构数据:', userMap);
        
        // 条件映射
        const processed = users.map(user => {
