### 实例方法与静态方法

class中的方法分类和使用场景：

```javascript
/**
 * 实例方法与静态方法示例
 */
const ClassMethodExamples = {
    /**
     * 方法类型对比
     */
    methodTypes() {
        console.log('=== 方法类型对比 ===');
        
        class MathUtils {
            constructor(value) {
                this.value = value;
            }
            
            // 实例方法（原型方法）
            square() {
                return this.value * this.value;
            }
            
            cube() {
                return this.value ** 3;
            }
            
            // 静态方法（类方法）
            static add(a, b) {
                return a + b;
            }
            
            static multiply(a, b) {
                return a * b;
            }
            
            static PI = Math.PI;
            
            // 静态方法中不能访问this.value
            static createSquare(side) {
                return new MathUtils(side);
            }
        }
        
        const math = new MathUtils(5);
        
        console.log('实例方法调用:');
        console.log('square:', math.square());
        console.log('cube:', math.cube());
        
        console.log('静态方法调用:');
        console.log('add:', MathUtils.add(10, 20));
        console.log('multiply:', MathUtils.multiply(3, 4));
        console.log('PI:', MathUtils.PI);
        
        console.log('静态工厂方法:');
        const square = MathUtils.createSquare(3);
        console.log('created square area:', square.square());
        
        // 实例不能访问静态方法
        console.log('实例访问静态方法:', math.add); // undefined
        console.log('类访问实例方法:', MathUtils.square); // undefined
    },
    
    /**
     * 高级方法模式
     */
    advancedMethodPatterns() {
        console.log('=== 高级方法模式 ===');
        
        class FluentAPI {
            constructor(value = 0) {
                this.value = value;
            }
            
            // 链式调用方法
            add(n) {
                this.value += n;
                return this; // 返回this支持链式调用
            }
            
            multiply(n) {
                this.value *= n;
                return this;
            }
            
            subtract(n) {
                this.value -= n;
                return this;
            }
            
            // 终结方法
            result() {
                return this.value;
            }
            
            // 静态链式创建
            static create(value) {
                return new FluentAPI(value);
            }
            
            // 条件方法
            if(condition, callback) {
                if (condition) {
                    callback(this);
                }
                return this;
            }
        }
        
        // 链式调用示例
        const result1 = FluentAPI
            .create(10)
            .add(5)
            .multiply(2)
            .subtract(3)
            .result();
        
        console.log('链式调用结果:', result1);
        
        // 条件链式调用
        const result2 = new FluentAPI(100)
            .if(true, api => api.add(50))
            .if(false, api => api.multiply(10))
            .multiply(2)
            .result();
        
        console.log('条件链式结果:', result2);
        
        // 方法装饰器模式
        class Logger {
            static methodLogger(target, propertyKey, descriptor) {
                const originalMethod = descriptor.value;
                
                descriptor.value = function(...args) {
                    console.log(`调用方法 ${propertyKey}，参数:`, args);
                    const result = originalMethod.apply(this, args);
                    console.log(`方法 ${propertyKey} 返回:`, result);
                    return result;
                };
                
                return descriptor;
            }
        }
        
        class Calculator {
            @Logger.methodLogger
            add(a, b) {
                return a + b;
            }
            
            // 手动应用装饰器（如果环境不支持decorator语法）
            multiply(a, b) {
                return a * b;
            }
        }
        
        // 手动应用装饰器
        Logger.methodLogger(Calculator.prototype, 'multiply', Object.getOwnPropertyDescriptor(Calculator.prototype, 'multiply'));
        
        const calc = new Calculator();
        console.log('装饰器示例:');
        calc.add(10, 5);
        calc.multiply(3, 4);
    }
};

